-- 清理未使用的 AI 前端模块对应的数据库菜单
-- 版本: V3.9.2_28
-- 说明: 前端已删除 aiapp/aiwriter/aiposter/aimcp/ocr/wordtpl/dashboard-ai/评估器 等模块，
--       对应的 24 个数据库菜单需软删除，同步清理角色权限关联记录。
--       保留菜单：AI模型配置、AI知识库、提示词管理目录、AI提示词

-- ============================================================
-- 1. 软删除 24 个未使用的 AI 菜单
-- ============================================================
UPDATE sys_permission SET del_flag = 1
WHERE id IN (
    '1996422809213341698',   -- 应用门户
    '1893865471550578689',   -- AI应用管理
    '1930221213607591937',   -- AI应用管理-按钮1
