    '1930223034757611522',   -- AI流程设计-按钮3
    '1930223114757611522',   -- AI流程设计-按钮4(AI流程测试)
    '1930223132619112449',   -- AI流程设计-按钮5
    '2005541199412592642',   -- AI流程设计-按钮6
    '1895401981290643458',   -- AI聊天(hidden)
    '1980223355087781889',   -- MCP配置
    '2000880658872508417',   -- AI评估器
    '2012375501376606210',   -- AI工具箱(目录)
    '1912753560201089025',   -- OCR识别
    '2008516285254000642',   -- AI海报
    '2010623918706446338',   -- AI写作
    '2025070908023480210',   -- AI简历(wordtpl)
    '2025070908023490211',   -- AI简历-按钮1
    '2025070908023490212',   -- AI简历-按钮2
